import{_ as s,o as a,c as n,a2 as o}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"开发环境","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/environment.md","filePath":"zh/dev/environment.md"}'),i={name:"zh/dev/environment.md"};function t(c,e,l,p,d,r){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="开发环境" tabindex="-1">开发环境 <a class="header-anchor" href="#开发环境" aria-label="Permalink to &quot;开发环境&quot;">​</a></h1><p>如何从一台全新机器到动手改内核 —— 工具链契约、两道 依赖门禁、免 root 沙箱安装，以及你将要游走的目录布局。</p><h2 id="_1-需求" tabindex="-1">1. 需求 <a class="header-anchor" href="#_1-需求" aria-label="Permalink to &quot;1. 需求&quot;">​</a></h2><ul><li>一台 Linux 宿主机（Debian/Ubuntu 已测试；任何装有下列 软件包的系统均可）。Windows：WSL2 给你的正是这套环境 （<code>build.ps1</code> 分发到它；MSYS2 缺 xorriso/grub）。</li><li><strong>发布工具链</strong>：gcc-14（Debian gcc 14.2.0 是发布版本 所用的编译器；CI 优先 <code>gcc-14</code>、回退 <code>gcc</code>）、binutils <code>ld</code>、<strong>nasm 2.16.03</strong>、xorriso <strong>1.5.6</strong>、mtools、 grub-common + grub-pc-bin + grub-efi-amd64-bin、 python3（3.9+）、zip。</li><li>测试用：<strong>qemu-system-x86 10.0.13</strong>、<strong>OVMF</strong>、seabios、 ipxe-qemu。</li><li>E2E 套件用：Python <code>pexpect</code>（回归、mega 应用冒烟）和 <code>paramiko</code>（SSH E2E）。</li><li>仅交叉引导外壳需要：<code>gcc-aarch64-linux-gnu</code>、 <code>gcc-riscv64-linux-gnu</code>（GCC &gt;= 12）。</li></ul><p>存在两个不同的 &quot;check_deps&quot; —— 不要混淆：</p><ol><li><strong>宿主软件包检查</strong> —— <code>tools/build.sh</code> 校验构建集 （gcc、ld/binutils、nasm、grub-mkimage/grub-common、 xorriso、mformat+mcopy/mtools、python3、zip），逐命令 打印对应的 Debian 软件包；<code>--install</code> 以 root 执行 apt 安装，否则指向下面的免 root 替代方案。</li><li><strong>架构门禁</strong> —— <code>tools/check_deps.py</code> 对 <code>ocos/{kernel,drivers,services,l1apps}</code> 强制执行 <em>依赖方向</em>： <ul><li>kernel 不得 include 任何解析到 <code>drivers/</code> 或 <code>services/</code> 之下的内容（例外：<code>core_boot_*.c</code> 组合 根），</li><li>drivers 不得 include services，</li><li>l1apps 只能 include <code>ocos/interface/</code> 所有的头文件，</li><li>按真实文件清单解析纯基名 <code>#include &quot;x.h&quot;</code>；任何违规 都以 file:line、该 include 及解析到的所有者退出码 1。 在发布卫生检查之前运行它（它未接入 CI）。</li></ul></li></ol><h2 id="_2-免-root-沙箱安装" tabindex="-1">2. 免 root 沙箱安装 <a class="header-anchor" href="#_2-免-root-沙箱安装" aria-label="Permalink to &quot;2. 免 root 沙箱安装&quot;">​</a></h2><p><code>tools/install-toolchain.sh</code> 下载 Debian <code>.deb</code> 并用 <code>dpkg -x</code> 解压到 <code>$OC_OPT</code>（默认 <code>/home/z/opt/extract</code>）—— 约 117 个软件包：nasm 2.16.03、 qemu-system-x86 10.0.13（+ data + 库）、xorriso 1.5.6、 grub-pc-bin + grub-efi-amd64-bin + grub-common、mtools、 ovmf、seabios。gcc 本身来自系统。然后：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source tools/env-sandbox.sh   # exports OC_TOOLS, PATH, LD_LIBRARY_PATH</span></span></code></pre></div><p>或者直接把 Makefile 指向该树： <code>make OC_TOOLS=&lt;tree&gt; ...</code> —— 它会探测 <code>&lt;tree&gt;/usr/...</code> 与 <code>&lt;tree&gt;/...</code> 两种布局；<code>OVMF_FD</code>/<code>QEMU_DATADIR</code>/ <code>SEABIOS_DIR</code> 由 <code>OC_TOOLS</code> 推导，且可单独覆盖。</p><h2 id="_3-获取代码树与健全性构建" tabindex="-1">3. 获取代码树与健全性构建 <a class="header-anchor" href="#_3-获取代码树与健全性构建" aria-label="Permalink to &quot;3. 获取代码树与健全性构建&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/cubestudio-dev/OpenCubeOS.git</span></span>
<span class="line"><span>cd OpenCubeOS</span></span>
<span class="line"><span>make all             # userprogs + kernel + ISO + src zip + OTA pkg</span></span>
<span class="line"><span>make test            # host unit tests</span></span>
<span class="line"><span>make run-bios        # boot it</span></span></code></pre></div><p>三步都通过，你的环境就是好的。注意 CI 以 <code>fetch-depth: 0</code> 克隆 —— 构建 id 是 <code>git rev-list --count HEAD + 21</code>，浅克隆会烘出一个低于 已发布版本的构建 id（每台已安装的机器都会把这个发布 当作&quot;降级&quot;而忽略）。一次变更的完整门槛见 <a href="./../root/CONTRIBUTING.html">CONTRIBUTING.md</a>。</p><h2 id="_4-仓库布局" tabindex="-1">4. 仓库布局 <a class="header-anchor" href="#_4-仓库布局" aria-label="Permalink to &quot;4. 仓库布局&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ocos/kernel/      L0 core: boot chain, sched, PMM/VMM/heap, usermode</span></span>
<span class="line"><span>ocos/kernel/arch/x86_64/  the 64-bit arch layer (cross archs in build.mk)</span></span>
<span class="line"><span>ocos/services/    one folder per service facet: block, net, audio,</span></span>
<span class="line"><span>                  fs, selfhost (OTA), power, diag, health, klog,</span></span>
<span class="line"><span>                  watchdog, display, tui, crypto, camera, usb, ...</span></span>
<span class="line"><span>ocos/drivers/     one folder per class: storage, net, audio, bus</span></span>
<span class="line"><span>                  (pci/acpi/i2c), usb, input, display, time, misc</span></span>
<span class="line"><span>ocos/interface/   the ring-3 contract headers: l1_lib.h,</span></span>
<span class="line"><span>                  l1svc_ops.h, i18n.h, wizard_lib.h, fs_lib.h,</span></span>
<span class="line"><span>                  editor_core.h, oc_l1_api.h, crt0.asm</span></span>
<span class="line"><span>ocos/l1apps/      one command = one app = one folder (284 programs)</span></span>
<span class="line"><span>                  + _i18n/ for the flat legacy test programs</span></span>
<span class="line"><span>ocire/            the independent recovery kernel (second L0)</span></span>
<span class="line"><span>ocbl/             the in-tree bootloader (BIOS stage1 + EFI entry)</span></span>
<span class="line"><span>ocse/             the vendored install-environment kernel</span></span>
<span class="line"><span>tools/            build + test + docs generators (117 files)</span></span>
<span class="line"><span>tests/            host-side unit tests (make test)</span></span>
<span class="line"><span>docs/             this documentation tree (en + zh mirror)</span></span>
<span class="line"><span>etc/              the default /etc volume content + l0 i18n</span></span></code></pre></div><h2 id="_5-立刻就要遵守的约定" tabindex="-1">5. 立刻就要遵守的约定 <a class="header-anchor" href="#_5-立刻就要遵守的约定" aria-label="Permalink to &quot;5. 立刻就要遵守的约定&quot;">​</a></h2><ul><li><code>-Wall -Wextra -Werror</code> —— 零警告，无例外，适用于每个 组件。</li><li>每个文件都带 SPDX 头。</li><li>内核/服务可见的字符串是 ASCII 英文（它们是脚本 + 向导锚点契约）；人类界面通过 <code>tr_()</code> 以 en+zh 资源 渲染。</li><li>命令面只增不减（接口冻结；编号只追加 —— 见 <a href="./interface-dictionary.html">interface-dictionary.md</a>）。</li><li>大缓冲区放在堆（内核）或静态 BSS（ring 3）—— 内核镜像 被钉在 0x400000 以下（见 <a href="./build.html">build.md</a> 第 4 节）。</li></ul><h2 id="_6-qemu-配方" tabindex="-1">6. QEMU 配方 <a class="header-anchor" href="#_6-qemu-配方" aria-label="Permalink to &quot;6. QEMU 配方&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># quick BIOS boot, serial on stdio</span></span>
<span class="line"><span>qemu-system-x86_64 -m 512M -cdrom build/opencube.iso \\</span></span>
<span class="line"><span>    -netdev user,id=n1 -device e1000,netdev=n1 -serial mon:stdio -display none</span></span>
<span class="line"><span></span></span>
<span class="line"><span># UEFI (OVMF; the make target copies OVMF.fd to a pflash work copy)</span></span>
<span class="line"><span>qemu-system-x86_64 -m 512M -machine q35 \\</span></span>
<span class="line"><span>    -drive if=pflash,format=raw,file=OVMF_WORK.fd \\</span></span>
<span class="line"><span>    -cdrom build/opencube.iso -display none -serial mon:stdio</span></span>
<span class="line"><span></span></span>
<span class="line"><span># with a scratch disk + display for the TUI</span></span>
<span class="line"><span>qemu-system-x86_64 -m 512M -cdrom build/opencube.iso \\</span></span>
<span class="line"><span>    -drive file=scratch.qcow2,if=ide -netdev user,id=n1 \\</span></span>
<span class="line"><span>    -device e1000,netdev=n1</span></span>
<span class="line"><span></span></span>
<span class="line"><span># boot log to a file</span></span>
<span class="line"><span>... -serial file:boot.log</span></span></code></pre></div><p><code>make run-bios</code>、<code>make run-uefi</code>、<code>make run-bios-gui</code>、 <code>make run-uefi-gui</code>、<code>make run-bios-persist</code>、 <code>make shot-*</code> 封装了常见用法（包括全新 32 MiB <code>/etc</code> 卷的建立，让持久化测试从干净状态开始）。迁移过的工具链： <code>make OC_TOOLS=&lt;tree&gt; run-bios</code>。更深入的 QEMU 指南 —— 勘误、sendkey、固件路径 —— 见 <a href="./qemu-testing.html">qemu-testing.md</a>。</p><h2 id="_7-宿主单元测试" tabindex="-1">7. 宿主单元测试 <a class="header-anchor" href="#_7-宿主单元测试" aria-label="Permalink to &quot;7. 宿主单元测试&quot;">​</a></h2><p><code>make test</code>（<code>tools/run_host_tests.py</code>）从每个 <code>tests/host_*.c</code> 头部提取 gcc 命令行，重映射重构前路径， 在宿主编译器上编译并运行：加密向量（NIST AES/SHA/HMAC、 RSA、X.509、AEAD）、TLS 密钥调度、TCP 拥塞控制、 block-512 门禁、multiboot2 解析、BT/WiFi/相机/SCSI/ IR/触摸板子系统。若干套件在本地启用 ASAN；依赖夹具的 （openssl RSA/链夹具）在夹具缺失时声明 SKIP-FIXTURE。 这里的一次回归比一次启动循环的迭代快得多。完整清单： <a href="./host-tests.html">host-tests.md</a>。</p>`,22)])])}const m=s(i,[["render",t]]);export{u as __pageData,m as default};
